<a class="back-link" href="<?= e(url('orders')) ?>">← Volver a pedidos</a><?php if($error): ?><div class="alert alert-danger" role="alert"><?= e($error) ?></div><?php endif ?><form method="post" action="<?= e(url('order-save',$id?['id'=>$id]:[])) ?>" id="order-form"><?= csrf_field() ?><section class="panel"><h2>Datos del pedido</h2><div class="row g-3 mt-1"><?php foreach(['CustomerID'=>['Cliente *','customers','CustomerID','CompanyName'],'EmployeeID'=>['Empleado','employees','EmployeeID','name'],'ShipVia'=>['Transportista','shippers','ShipperID','CompanyName']] as $field=>[$label,$list,$key,$name]): ?><div class="col-md-4"><label class="form-label" for="<?= $field ?>"><?= $label ?></label><select class="form-select" id="<?= $field ?>" name="<?= $field ?>" <?= $field==='CustomerID'?'required':'' ?>><option value="">Seleccionar</option><?php foreach($options[$list] as $o): ?><option value="<?= e($o[$key]) ?>" <?= (string)($row[$field]??'')===(string)$o[$key]?'selected':'' ?>><?= e($o[$name]) ?></option><?php endforeach ?></select></div><?php endforeach ?><?php foreach(['OrderDate'=>'Fecha del pedido *','RequiredDate'=>'Fecha requerida','ShippedDate'=>'Fecha de envío'] as $field=>$label): ?><div class="col-md-4"><label class="form-label" for="<?= $field ?>"><?= $label ?></label><input class="form-control" type="date" id="<?= $field ?>" name="<?= $field ?>" value="<?= e(substr($row[$field]??'',0,10)) ?>" <?= $field==='OrderDate'?'required':'' ?>></div><?php endforeach ?></div></section><section class="panel mt-4"><div class="panel-heading"><div><h2>Productos del pedido</h2><p>Descuento expresado como fracción: 0.10 = 10 %. Las existencias se ajustan al guardar.</p></div><button class="btn btn-outline-primary" type="button" id="add-line">+ Producto</button></div><div class="table-responsive"><table class="table order-lines"><thead><tr><th>Producto</th><th>Cantidad</th><th>Precio USD</th><th>Descuento</th><th></th></tr></thead><tbody id="order-lines"><?php foreach(array_values($row['lines']??[]) as $i=>$line): require ROOT.'/app/Views/orders/line.php';endforeach ?></tbody></table></div><p class="small text-secondary">Cada producto se admite una sola vez. Los productos descontinuados no admiten incrementos.</p></section>
<template id="line-template"><?php $i='__INDEX__';$line=[];require ROOT.'/app/Views/orders/line.php'; ?></template>
<section class="panel mt-4"><h2>Envío</h2><div class="row g-3 mt-1"><?php foreach(['ShipName'=>['Destinatario',40],'ShipAddress'=>['Dirección',60],'ShipCity'=>['Ciudad',15],'ShipRegion'=>['Región',15],'ShipPostalCode'=>['Código postal',10],'ShipCountry'=>['País',15]] as $field=>[$label,$max]): ?><div class="col-md-6"><label class="form-label" for="<?= $field ?>"><?= $label ?></label><input class="form-control" id="<?= $field ?>" name="<?= $field ?>" maxlength="<?= $max ?>" value="<?= e($row[$field]??'') ?>"></div><?php endforeach ?><div class="col-md-6"><label class="form-label" for="Freight">Flete USD</label><input type="number" class="form-control" id="Freight" name="Freight" min="0" max="999999.9999" step="0.0001" value="<?= e($row['Freight']??'0') ?>" required></div></div><div class="form-actions"><button class="btn btn-primary">Guardar pedido</button><a class="btn btn-light" href="<?= e(url('orders')) ?>">Cancelar</a></div></section></form>
